using System;using System.Linq;using System.IO;using System.Text;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CoastalGapAudit{static CoastalGapAudit(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("CoastalGapAudit.request")||EditorApplication.isCompiling)return;File.Delete("CoastalGapAudit.request");var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var log=new StringBuilder();var read=typeof(FinalPNGCityDetails).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic);foreach(var root in scene.GetRootGameObjects())foreach(var f in root.GetComponentsInChildren<MeshFilter>(true)){if(root.name=="Coastal Rocky Terrain")continue;var r=f.GetComponent<MeshRenderer>();if(!r)continue;var b=r.bounds;if(b.max.x<330||b.min.x>380||b.max.z<548||b.min.z>600)continue;var data=read.Invoke(null,new object[]{f.sharedMesh});var p=((Vector3[])data.GetType().GetField("p").GetValue(data)).Select(f.transform.TransformPoint).ToArray();var ids=(int[])data.GetType().GetField("ids").GetValue(data);var uv=(Vector2[][])data.GetType().GetField("uv").GetValue(data);if(uv[0]==null||!r.sharedMaterial)continue;foreach(var q in new[]{new Vector2(350,565),new Vector2(350,580),new Vector2(365,575)})for(int i=0;i<ids.Length;i+=3){var a=p[ids[i]];var c=p[ids[i+1]];var d=p[ids[i+2]];var av=new Vector2(a.x,a.z);var cv=new Vector2(c.x,c.z);var dv=new Vector2(d.x,d.z);float den=Cross(av,cv,dv);if(Mathf.Abs(den)<.001)continue;float u=Cross(q,cv,dv)/den,v=Cross(av,q,dv)/den,w=1-u-v;if(u<0||v<0||w<0)continue;log.AppendLine(q+" "+root.name+"/"+f.name+" y="+(u*a.y+v*c.y+w*d.y)+" material="+r.sharedMaterial.name+" uv0="+uv[0][ids[i]]+" slice="+Mathf.FloorToInt(uv[0][ids[i]].x/32));}}
for(int i=1;i<=5;i++){var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/3D/Fbx/Materials/Road 0"+i+".mat");log.AppendLine("ROAD SLOT "+(i-1)+" "+(mat.GetTexture("_BaseMap")?mat.GetTexture("_BaseMap").name:"null"));}var terrain=scene.GetRootGameObjects().Single(g=>g.name=="Coastal Rocky Terrain").GetComponentInChildren<Terrain>();foreach(var point in new[]{new Vector3(350,0,565),new Vector3(500,0,570),new Vector3(550,0,580),new Vector3(600,0,575)}){var origin=terrain.transform.position;var size=terrain.terrainData.size;int x=Mathf.FloorToInt((point.x-origin.x)/size.x*512),z=Mathf.FloorToInt((point.z-origin.z)/size.z*512);log.AppendLine("MASK "+point+" hole="+terrain.terrainData.IsHole(x,z)+" height="+terrain.SampleHeight(point));}var cameraObject=new GameObject("Temporary gap projection");var camera=cameraObject.AddComponent<Camera>();camera.transform.position=new Vector3(365,130,680);camera.transform.LookAt(new Vector3(333,28,568));camera.fieldOfView=62;camera.aspect=1.4f;var plane=new Plane(Vector3.up,new Vector3(0,27.736f,0));foreach(var pixel in new[]{new Vector2(620,570),new Vector2(610,540),new Vector2(540,560)}){var ray=camera.ViewportPointToRay(new Vector3(pixel.x/1400,1-pixel.y/1000,0));if(plane.Raycast(ray,out float distance))log.AppendLine("GAPPIXEL "+pixel+" world="+ray.GetPoint(distance));}UnityEngine.Object.DestroyImmediate(cameraObject);foreach(var layer in terrain.terrainData.terrainLayers)log.AppendLine("LAYER "+layer.name+" texture="+layer.diffuseTexture.name+" remap="+layer.diffuseRemapMin+" "+layer.diffuseRemapMax);File.WriteAllText("FinalEnvironmentRoadReview/CoastalGapAudit.txt",log.ToString());}static float Cross(Vector2 a,Vector2 b,Vector2 p)=>(b.x-a.x)*(p.y-a.y)-(b.y-a.y)*(p.x-a.x);}
